const brandAssets = $('Fetch Brand Assets').all();
const refImages = $('Fetch Reference Images').all();
const webhookBody = $('Webhook').first().json.body;
const brandData = $('Fetch Brand').first().json;

const logo = brandAssets.find(a => a.json.asset_type === 'logo');
const images = brandAssets.filter(a => a.json.asset_type === 'asset' && a.json.mime_type && a.json.mime_type.startsWith('image/'));

// Pick a random reference image
const refImage = refImages[Math.floor(Math.random() * refImages.length)];
if (!refImage) throw new Error('No reference images found for this category');

const brandDescription = brandData.description || '';
const promptText = `I want to create a social media creative for ${brandData.name}.${brandDescription ? '\n\n' + brandDescription : ''}\n\nI have attached previously created brand social media posts. Study the design language carefully: colors, typography, decorative motifs, layout patterns. IMPORTANT: These reference posts contain a brand logo - ignore the logo entirely when studying design elements. The logo will be added as a separate overlay in post-processing and must NOT appear in any generated image.`;

const content = [
  { type: 'input_text', text: promptText }
];

// Logo is NOT sent to GPT — it will be overlaid via ImageKit in post-processing
images.slice(0, 5).forEach(a => {
  content.push({ type: 'input_image', image_url: a.json.file_url });
});

return [{
  json: {
    brandId: webhookBody.brandId,
    referenceCategoryId: webhookBody.referenceCategoryId,
    headline: webhookBody.headline,
    cta: webhookBody.cta,
    refImageUrl: refImage.json.file_url,
    logoUrl: logo ? logo.json.file_url : null,
    turn1Content: content
  }
}];

const turn1Response = $('Turn 1 - Brand Context').first().json;
const prev = $('Build Turn 1 Payload').first().json;
const posResponse = $('Detect Logo Position').first().json;

const outputArr = posResponse.output || [];
const msgItem = outputArr.find(function(o) { return o.type === 'message'; });
const rawPos = msgItem && msgItem.content && msgItem.content[0] ? msgItem.content[0].text.trim().toLowerCase() : 'bottom-left';
const validPositions = ['top-left', 'top-center', 'top-right', 'bottom-left', 'bottom-center', 'bottom-right'];
const logoPosition = validPositions.indexOf(rawPos) >= 0 ? rawPos : 'bottom-left';

const logoRow = logoPosition.startsWith('top') ? 'top' : 'bottom';

// Extract brand style context from Turn 1 GPT response
const turn1Text = (turn1Response.output || []).find(o => o.type === 'message')?.content?.[0]?.text || '';

const layoutRef = 'LAYOUT REFERENCE (use this for positioning and composition only — do NOT use colors, fonts, or brand elements from this. Use brand colors, fonts, and elements from the brand context below):\n- Top 100px: Clean space for brand logo, centered\n- Upper 60% of the image: Large lifestyle or product imagery placed inside a rounded rectangle background shape, centered. Floating UI cards or feature callout chips overlaid on top of the imagery to highlight key features or stats\n- Bottom 40% of the image: Clean background area with a large bold headline in 2 lines, left-aligned or centered, with accent color on key words. No CTA button — the headline is the focal point at the bottom\n- Overall composition is clean with generous padding around all elements';
const line1 = 'Generate a social media post image using the layout described above.';
const line2 = 'Use ONLY the brand colors, fonts, and visual style from the brand context. Do not copy colors or design elements from the layout reference.';
const line3 = 'Headline: ' + prev.headline + ' | CTA: ' + prev.cta;
const brandContext = turn1Text ? 'Brand context (colors, fonts, visual style to use):\n' + turn1Text + '\n\n' : '';
const promptText = layoutRef + '\n\n' + brandContext + line1 + '\n\n' + line2 + '\n\n' + line3;

const requestBody = JSON.stringify({
  model: 'gpt-image-1.5',
  prompt: promptText,
  size: '1024x1024',
  quality: 'high',
  n: 1
});

return [{ json: { previousResponseId: turn1Response.id, refImageUrl: prev.refImageUrl, headline: prev.headline, cta: prev.cta, brandId: prev.brandId, referenceCategoryId: prev.referenceCategoryId, logoUrl: prev.logoUrl, logoPosition: logoPosition, requestBody: requestBody } }];

const turn2 = $('Turn 2 - Generate Image').first().json;
const meta = $('Build Turn 2 Payload').first().json;

const imageData = turn2.data && turn2.data[0];
if (!imageData || !imageData.b64_json) throw new Error('No image data in response');

const base64 = imageData.b64_json;
const storagePath = `${meta.brandId}/${Date.now()}_post.png`;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(base64, 'base64'),
  'post.png',
  'image/png'
);

return [{
  json: {
    brandId: meta.brandId,
    referenceCategoryId: meta.referenceCategoryId,
    headline: meta.headline,
    cta: meta.cta,
    storagePath,
    imageUrl: null /* set after ImageKit upload */,
    logoUrl: meta.logoUrl,
    logoPosition: meta.logoPosition
  },
  binary: {
    data: binaryData
  }
}];

const qcResponse = $('QC Check').first().json;
const meta = $('Resolve ImageKit URL').first().json;

const outputText = qcResponse.output?.find(o => o.type === 'message')?.content?.[0]?.text || '{"passed": true, "issues": []}';

let qcResult;
try {
  const cleaned = outputText.replace(/```json\n?|\n?```/g, '').trim();
  qcResult = JSON.parse(cleaned);
} catch(e) {
  qcResult = { passed: true, issues: ['QC parse error - skipping'] };
}

return [{
  json: {
    brandId: meta.brandId,
    referenceCategoryId: meta.referenceCategoryId,
    headline: meta.headline,
    cta: meta.cta,
    storagePath: meta.storagePath,
    imageUrl: meta.imageUrl,
    qcPassed: qcResult.passed !== false,
    qcIssues: qcResult.issues || []
  }
}];

const uploaded = $('Upload to ImageKit').first().json;
const meta = $('Extract and Prepare Image').first().json;
const endpoint = '__IMAGEKIT_URL_ENDPOINT__'.replace(/\/$/, '');
let imageUrl = uploaded.url;
if (!imageUrl) throw new Error('ImageKit upload failed: ' + JSON.stringify(uploaded));

// Optional logo overlay when brand logo is already on ImageKit
const logoUrl = meta.logoUrl;
if (logoUrl && typeof logoUrl === 'string' && logoUrl.startsWith(endpoint)) {
  let logoPath = logoUrl.slice(endpoint.length).replace(/^\/tr:[^/]+/, '').split('?')[0];
  if (logoPath.startsWith('/')) logoPath = logoPath.slice(1);
  const overlayPath = logoPath.replace(/\//g, '@@');
  const basePath = String(uploaded.filePath || '').replace(/^\//, '');
  if (overlayPath && basePath) {
    imageUrl = endpoint + '/tr:l-image,i-' + overlayPath + ',w-220,lx-40,ly-40,l-end/' + basePath;
  }
}

return [{
  json: {
    ...meta,
    imageUrl,
    imageKitFileId: uploaded.fileId || null,
    imageKitFilePath: uploaded.filePath || null,
  }
}];
